export const CHEST_REVEAL_SECONDS = 5;
const ease = (v) => { const t = Math.max(0, Math.min(1, v)); return t * t * (3 - 2 * t); };
export function createGuideRevealCamera() {
  const start = new THREE.Vector3(), startLook = new THREE.Vector3();
