      start.copy(position); startLook.copy(look);
      focus.copy(shot.focus || { x: REALITY_CHEST.x, y: .48, z: REALITY_CHEST.z });
      close.copy(shot.position || { x: REALITY_CHEST.x + 2.3, y: 2.15, z: REALITY_CHEST.z + 3.3 });
