.halloween-chest-reveal button { justify-self:center; min-height:44px; padding:8px 20px; border:1px solid #9ec8be66; border-radius:7px; background:#a8e5d81a; color:#d6faed; font-size:12px; }
.is-guide-reveal .halloween-nav,.is-guide-reveal .halloween-archive-status { visibility:hidden; pointer-events:none; }
.halloween-guide-backdrop { position:absolute; z-index:35; inset:0; display:grid; place-items:center; padding:20px; background:#070c14b8; }
.halloween-guide-panel { display:flex; flex-direction:column; width:min(780px,100%); max-height:calc(100dvh - 40px); border:1px solid #9ec6c752; border-radius:18px; background:linear-gradient(135deg,#192932,#141623 60%); color:#f2f2eb; font-family:system-ui,sans-serif; box-shadow:0 25px 80px #0009; overflow:hidden; }
.halloween-guide-panel header { display:flex; justify-content:space-between; align-items:center; padding:24px 28px; border-bottom:1px solid #ffffff12; }
.halloween-guide-panel header small { color:#9dcec7; font-size:9px; letter-spacing:.18em; font-weight:700; }
.halloween-guide-panel h2 { margin:7px 0 0; font-size:28px; letter-spacing:-.035em; }
.halloween-guide-panel header button { width:44px; height:44px; flex:none; border:1px solid #b6d9da30; border-radius:50%; background:#ffffff05; color:#e1eeec; }
.halloween-guide-body { min-height:0; overflow:auto; display:grid; grid-template-columns:1fr 1fr; gap:25px; padding:24px 28px; }
.halloween-guide-current { align-self:start; padding:22px; border:1px solid #86cbb33d; border-radius:12px; background:#9cead009; }
.halloween-guide-current > svg { color:#a7e6dc; }
.halloween-guide-current h3 { margin:12px 0; font-size:21px; letter-spacing:-.02em; }
.halloween-guide-current p { margin:0 0 20px; color:#d2dfdc; font-size:14px; line-height:1.65; }
.halloween-guide-current small { display:block; color:#97acae; font-size:11px; line-height:1.5; margin-top:16px; }
.halloween-guide-current button { display:flex; gap:8px; align-items:center; min-height:44px; padding:9px 12px; border:1px solid #c4dfba55; border-radius:7px; background:#a8dfbd10; color:#daeed6; font-size:12px; }
.halloween-guide-checklist h3 { margin:0 0 16px; font-size:14px; }
.halloween-guide-checklist ul { margin:0; padding:0; list-style:none; display:grid; gap:14px; }
.halloween-guide-checklist li { display:flex; gap:11px; color:#e6e8e5; font-size:12px; line-height:1.4; }
.guide-check { width:20px; height:20px; flex:none; display:grid; place-items:center; border:1px solid #b5caca40; border-radius:50%; color:#b3edca; }
.is-done .guide-check { border-color:#a3dcba66; background:#a3dcba18; }
.halloween-guide-checklist small { display:block; color:#98acae; font-size:11px; margin-top:3px; }
.halloween-guide-checklist .is-done small { color:#a7d7be; }
.halloween-guide-panel footer { display:flex; justify-content:space-between; align-items:center; gap:22px; padding:18px 28px; border-top:1px solid #ffffff12; }
.halloween-guide-panel footer p { margin:0; max-width:440px; color:#a3b5ba; font-size:11px; line-height:1.55; }
.halloween-guide-panel footer button { display:flex; gap:12px; align-items:center; justify-content:center; flex:none; min-height:44px; padding:10px 18px; border:1px solid #b9dfd5; border-radius:7px; background:#b9dfd5; color:#122a2d; font-size:12px; font-weight:700; }
@media(pointer:coarse) { .halloween-game { --guide-controls-floor:202px; } .halloween-objective { top:145px; } }
