.halloween-objective { position:absolute; z-index:9; top:155px; left:clamp(20px,3vw,48px); display:flex; align-items:flex-start; gap:12px; width:min(360px,calc(100vw - 40px)); padding:14px; border:1px solid #b8d7db55; border-radius:12px; background:linear-gradient(125deg,#142530f5,#14131ff5); color:#f3f4ef; text-align:left; box-shadow:0 8px 28px #0005,inset 3px 0 #9ae6dc; }
.halloween-objective-icon { display:grid; place-items:center; flex:none; width:34px; height:34px; border:1px solid #b5eee533; border-radius:10px; color:#a7e6dc; background:#83e5d912; }
.halloween-objective > span:nth-child(2) { display:grid; gap:6px; }
.halloween-objective small { color:#a4d4d0; font-size:9px; font-weight:700; letter-spacing:.16em; }
.halloween-objective strong { font-size:15px; line-height:1.25; }
.halloween-objective em { color:#c2cbd1; font-size:12px; font-style:normal; line-height:1.5; }
.halloween-objective-more { flex:none; color:#a7e6dc; margin-left:auto; }
.halloween-nav .halloween-guide-nav { color:#c5f4e9; border-color:#8fc9c2; background:#182b32f2; }
.halloween-guide-marker { position:absolute; top:0; left:0; z-index:5; justify-items:center; gap:2px; max-width:145px; text-align:center; pointer-events:none; color:#e0fff4; filter:drop-shadow(0 2px 4px #000); }
.guide-marker-arrow { font:700 32px/1 system-ui,sans-serif; color:#a8f1df; }
.halloween-guide-marker strong { padding:3px 8px; border:1px solid #8cd2c366; border-radius:5px; background:#10252deb; font:600 11px/1.3 system-ui,sans-serif; }
.halloween-guide-marker small { font:600 10px/1.3 system-ui,sans-serif; }
.halloween-bottom-stack { position:absolute; z-index:13; left:50%; bottom:calc(var(--guide-controls-floor) + env(safe-area-inset-bottom,0px)); transform:translateX(-50%); width:min(620px,calc(100vw - 36px)); display:flex; flex-direction:column-reverse; align-items:center; gap:8px; pointer-events:none; }
